<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import {Gamepad2,Coins,Trophy,Pause,Play,Volume2,VolumeX,ArrowLeft} from 'lucide-vue-next'
import DogSprite from './DogSprite.vue'
import {db,fail,friendly} from '../lib/supabase'
import {user} from '../lib/session'
import {newFlight,stepFlight,STEP_MS} from '../lib/flappy'
const props=defineProps<{disabled?:boolean;accessory?:string}>(),emit=defineEmits<{updated:[];active:[value:boolean]}>()
const shell=ref<HTMLElement|null>(null),field=ref<HTMLElement|null>(null)
const mode=ref<'menu'|'ready'|'playing'|'paused'|'result'>('menu'),flight=ref(newFlight(1)),busy=ref(false),error=ref(''),best=ref(0),ranks=ref<{alias:string;score:number}[]>([]),showRanks=ref(false),sound=ref(false),award=ref<{score:number;coins:number;xp:number;best:number}|null>(null)
let run:{id:string;seed:number}|null=null,taps:number[]=[],queued=false,lastTap=-10,raf=0,lastTime=0,accumulator=0,context:AudioContext|null=null,owner='',mounted=true
const progress=computed(()=>Math.floor(flight.value.tick/60))
function tone(freq:number){if(!sound.value)return;try{context??=new AudioContext();void context.resume();const o=context.createOscillator(),g=context.createGain();o.connect(g);g.connect(context.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,context.currentTime);g.gain.exponentialRampToValueAtTime(.001,context.currentTime+.09);o.start();o.stop(context.currentTime+.1)}catch{/* Audio is optional. */}}
async function records(){const {data,error:e}=await db.rpc('wedding_flappy_records');if(!e&&mounted){best.value=data.best;ranks.value=data.ranking}}
async function start(){if(busy.value||props.disabled||!user.value)return;busy.value=true;error.value='';owner=user.value.id;try{const {data,error:e}=await db.rpc('wedding_flappy_start');fail(e);if(!mounted||owner!==user.value?.id)return;run=data;flight.value=newFlight(data.seed);taps=[];lastTap=-10;queued=false;award.value=null;mode.value='ready';emit('active',true);emit('updated');await nextTick();shell.value?.scrollIntoView({block:'start',behavior:'instant'});field.value?.focus({preventScroll:true})}catch(e){error.value=friendly(e)}finally{busy.value=false}}
function schedule(){lastTime=performance.now();accumulator=0;raf=requestAnimationFrame(frame)}
function tap(){if(mode.value==='ready'){mode.value='playing';queued=true;field.value?.focus({preventScroll:true});schedule()}else if(mode.value==='playing'&&flight.value.tick-lastTap>=4)queued=true}
function frame(time:number){if(mode.value!=='playing')return;const delta=time-lastTime;lastTime=time;if(delta>350){pause();return}accumulator+=delta
 while(accumulator>=STEP_MS&&!flight.value.dead){const jump=queued&&flight.value.tick+1-lastTap>=4;if(jump){lastTap=flight.value.tick+1;taps.push(lastTap);queued=false;tone(560)}const old=flight.value.score;stepFlight(flight.value,jump);if(flight.value.score>old)tone(850);accumulator-=STEP_MS}
 if(flight.value.dead){mode.value='result';tone(180);void finish();return}raf=requestAnimationFrame(frame)
}
function pause(){if(mode.value!=='playing')return;cancelAnimationFrame(raf);queued=false;mode.value='paused'}
function resume(){mode.value='playing';field.value?.focus({preventScroll:true});schedule()}
async function finish(){if(!run||busy.value||award.value)return;busy.value=true;error.value='';try{const {data,error:e}=await db.rpc('wedding_flappy_finish',{run_id:run.id,taps,ticks:flight.value.tick});fail(e);if(!mounted||owner!==user.value?.id)return;award.value=data;best.value=data.best;emit('updated');void records()}catch(e){if(mounted)error.value=friendly(e)}finally{busy.value=false}}
function leave(){cancelAnimationFrame(raf);mode.value='menu';emit('active',false);run=null}
function key(e:KeyboardEvent){
 if(!['ready','playing','paused'].includes(mode.value)||e.ctrlKey||e.metaKey||e.altKey)return
 const target=e.target as HTMLElement|null
 if(target?.isContentEditable||target?.closest('input,textarea,select,[role="dialog"]'))return
 if(target&&target!==document.body&&!shell.value?.contains(target))return
 if(['KeyP','Escape'].includes(e.code)){e.preventDefault();e.stopPropagation();if(!e.repeat){if(mode.value==='playing')pause();else if(mode.value==='paused')resume()}return}
 if(['Space','ArrowUp'].includes(e.code)&&mode.value!=='paused'){e.preventDefault();e.stopPropagation();if(!e.repeat)tap()}
}
function hidden(){if(document.hidden)pause()}
watch(()=>user.value?.id,()=>{leave();award.value=null;best.value=0;ranks.value=[]})
onMounted(()=>{void records();window.addEventListener('keydown',key,true);document.addEventListener('visibilitychange',hidden)})
onUnmounted(()=>{mounted=false;cancelAnimationFrame(raf);window.removeEventListener('keydown',key,true);document.removeEventListener('visibilitychange',hidden);void context?.close();emit('active',false)})
</script>
<template><section ref="shell" class="flappy-game" :class="{'flight-active':mode!=='menu'}"><template v-if="mode==='menu'"><div class="arcade-heading"><Gamepad2/><div><h4>El patio de juegos</h4><p>Una pequeña aventura. Muchas patitas.</p></div></div><button class="flappy-card" :disabled="disabled||busy" @click="start"><div class="flight-cover"><DogSprite mood="playing"/></div><span><b>Flappy Perrito</b><small>Toca o pulsa espacio para saltar.</small><em>{{busy?'Preparando…':'¡Vamos a volar! →'}}</em></span></button><div class="flight-record"><Trophy :size="16"/> Tu récord: {{best}} arcos <button @click="showRanks=!showRanks">Clasificación</button></div><p class="arcade-note">Cada arco: 2 monedas + 3 XP · Máximo 60 monedas y 90 XP por partida.<br/>Jugar consume 3 de energía y 2 de comida. Hasta 60 segundos por aventura.</p><div v-if="showRanks" class="flappy-ranking"><p v-if="!ranks.length">Aún no hay marcas públicas. Puedes participar con tu alias desde tu perfil.</p><ol v-else><li v-for="r in ranks" :key="r.alias">{{r.alias}} <b>{{r.score}} arcos</b></li></ol></div></template><template v-else><header class="flight-toolbar"><button v-if="mode==='result'" :disabled="busy" @click="leave" aria-label="Volver al patio"><ArrowLeft :size="20"/></button><span v-else><Gamepad2 :size="20"/></span><b>Flappy Perrito</b><span>{{progress}} / 60 s</span><button @click="sound=!sound" :aria-label="sound?'Desactivar sonido':'Activar sonido'"><Volume2 v-if="sound" :size="19"/><VolumeX v-else :size="19"/></button><button v-if="mode==='playing'" @click="pause" aria-label="Pausar"><Pause :size="20"/></button></header><div ref="field" class="flight-field" tabindex="0" role="application" aria-label="Flappy Perrito. Toca para saltar o usa la barra espaciadora." @pointerdown.prevent="tap"><div class="flight-cloud c1"></div><div class="flight-cloud c2"></div><div class="flight-hills"></div><div v-for="(g,i) in flight.gates" :key="i" class="flight-gate" :style="{left:g.x/360+'%',width:5200/360+'%'}"><div class="gate-top" :style="{height:(g.center-7200)/480+'%'}"><span>❀</span></div><div class="gate-bottom" :style="{top:(g.center+7200)/480+'%'}"><span>❀</span></div></div><div class="flight-puppy" :style="{top:flight.y/480+'%',transform:`translate(-50%,-50%) rotate(${Math.max(-18,Math.min(28,flight.velocity/25))}deg)`}"><DogSprite mood="playing"/></div><div class="flight-score">{{flight.score}}</div><div v-if="mode==='ready'" class="flight-overlay"><div><span class="flight-big-icon">☝</span><h4>¡Prepara las patitas!</h4><p>Cada toque, un salto.<br/>¡Pasa por el hueco de los arcos!</p><small><b>PC:</b> espacio o ↑ para saltar.<br/><b>Móvil:</b> toca la pantalla.</small><button @pointerdown.stop @click.stop="tap">¡A volar!</button></div></div><div v-if="mode==='paused'" class="flight-overlay" @pointerdown.stop><div><Pause :size="32"/><h4>Una pequeña pausa</h4><p>Tu perrito te espera.</p><button @click="resume"><Play :size="16"/> Continuar</button><button class="flight-secondary" @click="leave">Salir sin recompensa</button></div></div><div v-if="mode==='result'" class="flight-overlay result" @pointerdown.stop><div><Trophy :size="32"/><h4>{{flight.score?'¡Buen vuelo!':'¡Otra y lo conseguimos!'}}</h4><p class="result-score">{{flight.score}} <small>arcos</small></p><p v-if="busy" role="status">Guardando tu aventura…</p><div v-else-if="award" class="flight-prizes"><span><Coins :size="16"/> +{{award.coins}}</span><span>✦ +{{award.xp}} XP</span></div><p v-if="award">Tu récord: {{best}} arcos</p><p v-if="error" class="flight-error" role="alert">{{error}}</p><button v-if="error&&!award" :disabled="busy" @click="finish">Reintentar guardar</button><button v-else :disabled="busy||disabled" @click="start">Volver a jugar</button><button :disabled="busy" class="flight-secondary" @click="leave">Volver al patio</button></div></div></div><div class="game-controls-guide"><span><b>PC</b> <kbd>Espacio</kbd> / <kbd>↑</kbd> saltar · <kbd>P</kbd> / <kbd>Esc</kbd> pausa</span><span><b>Móvil</b> Toca el campo para saltar.</span></div></template><p v-if="error&&mode==='menu'" class="pet-error" role="alert">{{error}}</p></section></template>
